            errors.append({repr(key): "expected string or bytes-like object"})
            continue

        key_str = key.decode("utf-8") if isinstance(key, bytes) else key

        if not _label_re.match(key_str):
            errors.append(
                {
                    f"{key_str}": f"Label key '{key_str}' does not match the regex {_label_re.pattern}"
                }
            )

        # Validate value type
        if not isinstance(value, (str, bytes)):
            errors.append({repr(value): "expected string or bytes-like object"})
            continue

        value_str = value.decode("utf-8") if isinstance(value, bytes) else value

        if not _label_re.match(value_str):
            errors.append(
                {
                    f"{value_str}": f"Label value '{value_str}' does not match the regex {_label_re.pattern}"
                }
            )

    if errors:
        raise ValidationError(errors)<|return|>

