def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.

    """

    # Basic type checks and graceful handling of invalid inputs
    if not isinstance(last_applied_manifest, list):
        raise TypeError("last_applied_manifest must be a list")
    if not isinstance(response, list):
        raise TypeError("response must be a list")
    if observer_schema is None:
        observer_schema = []

    # Iterate over the response elements and mirror them into the
    # ``last_applied_manifest`` list.
    for idx, resp_item in enumerate(response):
        # Ensure the destination list is long enough
        if idx >= len(last_applied_manifest):
            last_applied_manifest.append(None)

        # The observer schema can provide additional directives; use it if available.
        schema_item = None
        if idx < len(observer_schema):
            schema_item = observer_schema[idx]

        # Skip None values – they indicate absence of information
        if resp_item is None:
            continue

        # Handle nested dictionaries
        if isinstance(resp_item, dict):
            # Initialize destination entry if necessary
            if last_applied_manifest[idx] is None:
                last_applied_manifest[idx] = {}

            # Recursively update the dictionary if the helper is available
            try:
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[idx], schema_item, resp_item
                )
            except NameError:
                # Fallback: shallow update when the helper isn't defined
                last_applied_manifest[idx].update(resp_item)

        # Handle nested lists
        elif isinstance(resp_item, list):
            if last_applied_manifest[idx] is None:
                last_applied_manifest[idx] = []

            # Recursively update the nested list
            try:
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[idx], schema_item, resp_item
                )
            except RecursionError:
                # Avoid infinite recursion on malformed data
                pass

        # Handle scalar values
        else:
            if last_applied_manifest[idx] is None:
                last_applied_manifest[idx] = resp_item

    # No return value – the list is mutated in place. Return it for convenience.
    return last_applied_manifest<|return|>

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    Returns:
        dict: Mapping from resource kind to its generated default observer schema.
    """
    # Container for the schemas that need to be generated
    generated_schemas = {}

    try:
        # Attempt to retrieve the application's specification
        spec = getattr(app, "spec", None)
        if spec is None:
            return generated_schemas

        # Get the list/dict of Kubernetes resources in the manifest
        manifest = getattr(spec, "manifest", None)
        if not manifest:
            return generated_schemas

        # Existing observer schemas defined by the user
        existing_schemas = getattr(spec, "observer_schema", {})
        if existing_schemas is None:
            existing_schemas = {}

        # Normalize the manifest to a list of resource dictionaries
        # Accepts both a list/tuple and a dict (likely list under "items")
        resources = []
        if isinstance(manifest, (list, tuple)):
            resources = manifest
        elif isinstance(manifest, dict):
            # If the manifest dict contains an 'items' key, use that
            if "items" in manifest:
                items = manifest["items"]
                if isinstance(items, (list, tuple)):
                    resources = items
                else:
                    resources = [manifest]  # treat the whole dict as a single resource
            else:
                resources = [manifest]
        else:
            # Unsupported manifest type
            return generated_schemas

        for resource in resources:
            # We only handle dict resources that contain both 'kind' and 'metadata'
            if not isinstance(resource, dict):
                continue
            kind = resource.get("kind")
            if not kind:
                continue

            # Skip if a custom schema is already specified for this kind
            if kind in existing_schemas:
                continue

            # Generate a minimal default schema:
            # type object with no required properties
            default_schema = {
                "type": "object",
                "properties": {},
                # It can be extended later if needed
            }
            generated_schemas[kind] = default_schema

    except (AttributeError, TypeError, ValueError):
        # In case of any unexpected structure or runtime issue,
        # just return what has been generated so far (which may be empty)
        pass

    return generated_schemas
