def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # normalize path
        if path is None:
            return False
        # accept both str path and pyfs path objects
        if isinstance(path, str):
            if not os.path.isdir(path):
                return False
        else:
            # assume pyfs pathlike object
            if not path.isdir():
                return False

        # common OCFL checks
        # 1. HEAD file must exist
        head = os.path.join(path, 'HEAD')
        if isinstance(path, str):
            if not os.path.isfile(head):
                return False
        else:
            if not path.file('HEAD').isfile():
                return False

        # 2. content folder must exist
        content_dir = os.path.join(path, 'content')
        if isinstance(path, str):
            if not os.path.isdir(content_dir):
                return False
        else:
            if not path.isdir('content'):
                return False

        # 3. manifest.json must exist inside content
        manifest = os.path.join(content_dir, 'manifest.json')
        if isinstance(path, str):
            if not os.path.isfile(manifest):
                # allow missing manifest for very old OCFL objects
                pass
        else:
            # pyfs
            if path.isdir('content') and not path.file('content/manifest.json').isfile():
                pass

        # 4. optional id.json
        try:
            if isinstance(path, str):
                id_file = os.path.join(path, 'id.json')
                if os.path.isfile(id_file):
                    with open(id_file, 'r') as f:
                        json.load(f)
            else:
                if path.file('id.json').isfile():
                    json.load(path.file('id.json').open('r'))
        except Exception:
            # JSON parse error considered non-critical
            pass

        return True
    except Exception:
        # any unexpected issue means invalid
        return False
