def files_list(path):
    """
    Return the files in `path`.
    """
    import os

    # Validate input type
    if not isinstance(path, (str, bytes)):
        raise TypeError(f"Expected path as str or bytes, got {type(path).__name__}")

    # Check that path exists
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path does not exist: {path}")

    # Check that path is a directory
    if not os.path.isdir(path):
        raise NotADirectoryError(f"Path is not a directory: {path}")

    try:
        entries = os.listdir(path)
    except PermissionError as pe:
        raise PermissionError(f"Permission denied while accessing '{path}': {pe}") from pe
    except OSError as oe:
        # General OS error while listing
        raise RuntimeError(f"Failed to list contents of '{path}': {oe}") from oe

    # Filter only regular files
    files = []
    for entry in entries:
        full_path = os.path.join(path, entry)
        try:
            if os.path.isfile(full_path):
                files.append(entry)
        except OSError:
            # Skip entries that cause errors (e.g., broken symlinks)
            continue

    return files<|return|>

