        '2318-0889-tinf-33-0421/2318-0889-tinf-33-e200071-gf03.tif',
        '2318-0889-tinf-33-0421/2318-0889-tinf-33-e200071-gf04.tif',
    ]
    ```
    """
    if not isinstance(zip_path, (str, bytes)):
        raise TypeError(f"zip_path must be a string or bytes, got {type(zip_path).__name__}")
    if not zip_path:
        raise ValueError("zip_path must not be empty")

    try:
        import zipfile
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # Use info.is_dir() if available; fallback to name ending with '/'
            return [
                info.filename
                for info in zf.infolist()
                if not (info.is_dir() if hasattr(info, "is_dir") else info.filename.endswith('/'))
            ]
    except FileNotFoundError as exc:
        raise FileNotFoundError(f"Zip file not found: {zip_path}") from exc
    except zipfile.BadZipFile as exc:
        raise zipfile.BadZipFile(f"Invalid zip file: {zip_path}") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to read zip file '{zip_path}': {exc}") from exc<|return|>

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate arguments
    if not isinstance(indent, int):
        raise TypeError(f"indent must be an integer, got {type(indent).__name__}")
    if not isinstance(debug, bool):
        raise TypeError(f"debug must be a boolean, got {type(debug).__name__}")

    def _format_value(value, level):
        """
        Recursively format a value with indentation.
        """
        ind = " " * level
        try:
            # If the value itself knows how to pretty-print, use it
            if hasattr(value, "pretty") and callable(getattr(value, "pretty")):
                return value.pretty(level, debug)
            # Handle common built-ins
            if isinstance(value, dict):
                items = []
                if not value:
                    return "{}"
                for k in sorted(value):
                    items.append(f"{ind}    {repr(k)}: {_format_value(value[k], level + 4)}")
                return "{{\n" + "\n".join(items) + f"\n{ind}}}"
            if isinstance(value, (list, tuple, set)):
                opener, closer = ("[", "]"), ("(", ")"), ("{", "}")
                if isinstance(value, list):
                    opener, closer = "[", "]"
                if isinstance(value, tuple):
                    opener, closer = "(", ")"
                if isinstance(value, set):
                    opener, closer = "{", "}"
                if not value:
                    return opener + closer
                parts = []
                for item in value:
                    parts.append(f"{ind}    {_format_value(item, level + 4)}")
                return f"{opener}\n" + "\n".join(parts) + f"\n{ind}{closer}"
            # Primitive types
            return repr(value)
        except Exception:
            return "<Error formatting>"

    parts = [f"{' ' * indent}{self.__class__.__name__}("]
    attrs = getattr(self, "__dict__", {})
    if attrs:
        for key in sorted(attrs):
            val = attrs[key]
            try:
                formatted_val = _format_value(val, indent + 4)
            except Exception:
                formatted_val = "<Error>"
            parts.append(f"{' ' * (indent + 4)}{key}={formatted_val}")
    parts.append(f"{' ' * indent})")
    if debug:
        parts.append(f"{' ' * indent}Debug: {attrs!r}")
    return "\n".join(parts)<|return|>

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings.

    This decorator adapts a tzname function to return a bytestring when run
    in Python 3 while leaving the original behavior unchanged in Python 2.
    """
    if not callable(namefunc):
        raise TypeError("namefunc must be callable")
    import sys
    is_py3 = sys.version_info[0] >= 3
    def wrapper(*args, **kwargs):
        try:
            result = namefunc(*args, **kwargs)
        except Exception:
            # Propagate any exception raised by the wrapped function
            raise
        # Preserve None values
        if result is None:
            return None
        if is_py3:
            # In Python 3, convert str (unicode) to bytes
            if isinstance(result, str):
                try:
                    return result.encode('utf-8')
                except Exception:
                    # Fallback: encode with latin-1, ignoring errors
                    return result.encode('latin-1', errors='ignore')
            # If already bytes, just return it
            if isinstance(result, bytes):
                return result
        # In Python 2 or if result is not a str/bytes, return as-is
        return result
    return wrapper<|return|>

