def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    import os
    import hashlib

    # Ensure the storage root attribute exists and is a directory
    if not hasattr(self, "storage_root") or not isinstance(self.storage_root, str):
        raise ValueError(
            "The instance must have a 'storage_root' attribute pointing to a directory."
        )
    if not os.path.isdir(self.storage_root):
        raise ValueError(
            f"Provided storage_root path '{self.storage_root}' is not a directory or does not exist."
        )

    num_objects = 0
    good_objects = 0

    # Helper to compute digest in a memory‑safe way
    def _compute_digest(path: str) -> str:
        sha = hashlib.sha256()
        try:
            with open(path, "rb") as f:
                for chunk in iter(lambda: f.read(8192), b""):
                    sha.update(chunk)
            return sha.hexdigest()
        except Exception:
            # If we can't read the file, treat it as an error later
            return ""

    # Walk the directory tree
    for root, _dirs, files in os.walk(self.storage_root):
        for fname in files:
            num_objects += 1
            file_path = os.path.join(root, fname)
            valid = True

            # Basic validation: file must exist and be non‑empty
            if validate_objects:
                try:
                    if os.path.getsize(file_path) == 0:
                        valid = False
                except Exception:
                    valid = False

            # Optionally verify a SHA256 digest file exists and matches
            if check_digests and valid:
                digest_file = file_path + ".sha256"
                if os.path.isfile(digest_file):
                    try:
                        expected = ""
                        with open(digest_file, "r") as df:
                            expected = df.read().strip()
                        actual = _compute_digest(file_path)
                        if not actual or actual != expected:
                            valid = False
                    except Exception:
                        valid = False

            if valid:
                good_objects += 1
            elif show_warnings:
                try:
                    print(f"Warning: object '{file_path}' failed validation.")
                except Exception:
                    # Suppress any errors from printing
                    pass

    return num_objects, good_objects<|return|>

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # Ensure a root path has been supplied on the instance.
    if not hasattr(self, "root_path"):
        raise AttributeError("Instance missing 'root_path' attribute required for initialization.")

    root_path = self.root_path

    # If the root already exists we should not overwrite it.
    if os.path.exists(root_path):
        raise FileExistsError(f"The specified OCFL root '{root_path}' already exists.")

    try:
        # Create the root directory
        os.makedirs(root_path, exist_ok=False)

        # Create the required .ocfl-root subdirectory
        ocfl_root_dir = os.path.join(root_path, ".ocfl-root")
        os.makedirs(ocfl_root_dir, exist_ok=False)

        # Create a minimal index file in .ocfl-root
        index_file_path = os.path.join(ocfl_root_dir, "index.json")
        with open(index_file_path, "w", encoding="utf-8") as f:
            # A minimal placeholder JSON; actual content can be expanded later.
            f.write("{}")

        # Create a manifest sub‑directory for future object manifests
        manifest_dir = os.path.join(ocfl_root_dir, "manifest")
        os.makedirs(manifest_dir, exist_ok=False)

    except Exception as exc:
        # Roll back partially created structure to avoid leaving the file system in a broken state.
        def safe_rmtree(path):
            try:
                if os.path.isdir(path):
                    # Remove any files/directories that could have been created.
                    for root, dirs, files in os.walk(path, topdown=False):
                        for name in files:
                            try:
                                os.remove(os.path.join(root, name))
                            except Exception:
                                pass
                        for name in dirs:
                            try:
                                os.rmdir(os.path.join(root, name))
                            except Exception:
                                pass
                    os.rmdir(path)
            except Exception:
                pass

        safe_rmtree(root_path)
        raise RuntimeError(f"Failed to initialize OCFL storage root at '{root_path}': {exc}") from exc
    # Return None on successful creation
    return None<|return|>

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError(f"Expected str, got {type(version).__name__}")

    if not version:
        raise ValueError("Empty version string")

    parts = version.split('.')
    # Find the last part that is purely numeric
    idx = None
    for i in range(len(parts) - 1, -1, -1):
        part = parts[i]
        if part.isdigit():
            idx = i
            break
    if idx is None:
        raise ValueError("No numeric segment found in version string")

    orig = parts[idx]
    try:
        value = int(orig)
    except ValueError as e:
        raise ValueError(f"Invalid numeric part: {orig}") from e

    new_value = value + 1
    new_part = str(new_value)

    # Preserve leading zeros if the new value is shorter than the original length
    if len(new_part) < len(orig):
        new_part = orig[:len(orig) - len(new_part)] + new_part

    parts[idx] = new_part
    return '.'.join(parts)<|return|>

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import json

    # Find root inventory dictionary; raise if not available
    root_inventory = getattr(self, "root_inventory", None) or getattr(self, "_root_inventory", None)
    if root_inventory is None:
        raise AttributeError("Root inventory not set on the validator instance")

    # Prepare a container for differences: {file_path: {version_dir: digest}}
    self.different_digests = {}

    for vdir in version_dirs:
        # Expected inventory location (customizable if needed)
        inv_path = os.path.join(vdir, "inventory.json")

        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory file in version directory '{vdir}'")

        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inventory = json.load(f)
        except Exception as exc:
            raise ValueError(f"Could not load JSON inventory from '{inv_path}': {exc}")

        if not isinstance(inventory, dict):
            raise ValueError(f"Inventory at '{inv_path}' is not a JSON object")

        # Ensure all required files are present in the inventory (up to this point)
        # and record any digest differences compared to the root inventory.
        for path, digest in inventory.items():
            if path not in root_inventory:
                # new file introduced in this version; nothing to compare
                continue
            root_digest = root_inventory[path]
            if digest != root_digest:
                self.different_digests.setdefault(path, {})[vdir] = digest

    return True
<|return|>

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        import os
        if not os.path.exists(path):
            return f"path '{path}' not found"
        if os.path.isfile(path):
            return 'file'
        if os.path.isdir(path):
            for entry in os.listdir(path):
                full = os.path.join(path, entry)
                if os.path.isfile(full) and entry.startswith('0='):
                    return 'object'
            return 'root'
        return f"path '{path}' is not file or directory"
    except Exception as e:
        return f"error: {e}"
<|return|>

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Ensure we are working with a dictionary
    if params is None:
        params = {}
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")

    # Nothing to add
    if not bug_ids:
        return params

    # Normalise bug_ids to a list of strings
    if isinstance(bug_ids, (str, int)):
        bug_ids = [str(bug_ids)]
    elif not hasattr(bug_ids, "__iter__"):
        raise TypeError("bug_ids must be an iterable of bug identifiers")

    bug_id_list = []
    for bid in bug_ids:
        try:
            bid_str = str(bid).strip()
            if bid_str:
                bug_id_list.append(bid_str)
        except Exception:
            raise ValueError(f"Invalid bug identifier: {bid}") from None

    if not bug_id_list:
        return params

    # Merge with any existing 'ids' entry in params
    existing = []
    if "ids" in params:
        current = params["ids"]
        if isinstance(current, str):
            existing = [x.strip() for x in current.split(",") if x.strip()]
        elif isinstance(current, (list, set, tuple)):
            existing = [str(x).strip() for x in current if str(x).strip()]
    # Combine and de‑duplicate while preserving order
    combined = []
    seen = set()
    for item in existing + bug_id_list:
        if item not in seen:
            seen.add(item)
            combined.append(item)

    params["ids"] = ",".join(combined)
    return params<|return|>

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This
    allows common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    # Basic input validation
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("'unparsed_arguments' must be a sequence of strings")
    if not isinstance(subparsers, dict):
        raise TypeError("'subparsers' must be a dict of name: ArgumentParser")

    parsed_namespaces = {}
    # Start with full set of remaining arguments (unknown to every parser)
    remaining_candidates = None

    for name, parser in subparsers.items():
        if not isinstance(name, str):
            raise TypeError("All keys in 'subparsers' must be strings")
        if not hasattr(parser, "parse_known_args"):
            raise TypeError(f"Parser for key '{name}' does not provide parse_known_args method")

        try:
            namespace, unknown = parser.parse_known_args(unparsed_arguments)
        except Exception as exc:
            raise RuntimeError(f"Failed to parse arguments with subparser '{name}': {exc}") from exc

        parsed_namespaces[name] = namespace

        unknown_set = set(unknown)
        if remaining_candidates is None:
            remaining_candidates = unknown_set
        else:
            remaining_candidates &= unknown_set

    if remaining_candidates is None:
        remaining_args = list(unparsed_arguments)
    else:
        # Preserve original order and handle duplicates
        remaining_args = [arg for arg in unparsed_arguments if arg in remaining_candidates]

    return parsed_namespaces, remaining_args
<|return|>

def make_parsers():
    '''
    Build a top-level parser and its subparsers and return them as a tuple.
    '''
    # Import inside the function to avoid global imports as per instruction.
    try:
        import argparse
    except Exception as exc:
        raise RuntimeError("Failed to import argparse module") from exc

    # Create the main argument parser.
    try:
        parser = argparse.ArgumentParser()
    except Exception as exc:
        raise RuntimeError("Failed to create the main ArgumentParser") from exc

    # Create subparsers action.
    try:
        subparsers = parser.add_subparsers(dest='command')
    except Exception as exc:
        raise RuntimeError("Failed to create subparsers action") from exc

    return parser, subparsers<|return|>

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    def is_mapping(node):
        # Quick check based on tag; avoids importing ruamel.yaml
        try:
            return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map'
        except Exception:
            return False

    def merge_mappings(map1, map2):
        """
        Recursively merge two MappingNodes.
        Returns a new MappingNode instance.
        """
        merged_dict = {}
        # Add entries from the first mapping
        for k_node, v_node in getattr(map1, 'value', []):
            merged_dict[k_node.value] = (k_node, v_node)
        # Merge/override with entries from the second mapping
        for k_node, v_node in getattr(map2, 'value', []):
            key = k_node.value
            if key in merged_dict:
                existing_k, existing_v = merged_dict[key]
                if is_mapping(existing_v) and is_mapping(v_node):
                    merged_v = merge_mappings(existing_v, v_node)
                    merged_dict[key] = (existing_k, merged_v)
                else:
                    # Last value wins; keep the key node from the new pair
                    merged_dict[key] = (k_node, v_node)
            else:
                merged_dict[key] = (k_node, v_node)
        # Preserve the original mapping node's tag and marks
        merged_values = list(merged_dict.values())
        try:
            return type(map1)(tag=map1.tag, value=merged_values)
        except Exception:
            # Fallback: create a plain MappingNode-like object if constructor fails
            return MappingNode(tag=map1.tag, value=merged_values)

    if not isinstance(nodes, list):
        raise TypeError(f"Expected a list of node tuples, got {type(nodes).__name__}")
    merged = {}
    for pair in nodes:
        try:
            key_node, value_node = pair
        except Exception:
            raise ValueError(f"Each item must be a 2-tuple of (ScalarNode, value), got {pair!r}")
        key = getattr(key_node, 'value', None)
        if key is None:
            raise ValueError(f"Key node lacks a 'value' attribute: {key_node!r}")
        if key in merged:
            existing_key_node, existing_value_node = merged[key]
            if is_mapping(existing_value_node) and is_mapping(value_node):
                merged_value_node = merge_mappings(existing_value_node, value_node)
                merged[key] = (existing_key_node, merged_value_node)
            else:
                merged[key] = (key_node, value_node)
        else:
            merged[key] = (key_node, value_node)
    # Return the merged nodes while preserving the order of first appearance
    return [merged[key] for key in merged

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        if not hasattr(parser, "_actions"):
            raise TypeError("Expected an argparse.ArgumentParser instance")
        flags = []
        for action in parser._actions:
            # action.option_strings may be empty for positional arguments
            if hasattr(action, "option_strings") and action.option_strings:
                for opt in action.option_strings:
                    flags.append(opt)
        return " ".join(flags)
    except Exception as e:
        # Re-raise as a TypeError to signal misuse of the function
        raise TypeError(f"Invalid parser object: {e}") from e<|return|>

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("Parameter 'dicts' cannot be None")
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError(f"Parameter 'dicts' must be an iterable of dicts, not {type(dicts).__name__}")

    result = {}
    for idx, d in enumerate(iterator):
        if not isinstance(d, dict):
            raise TypeError(f"Element {idx} of 'dicts' must be a dict, not {type(d).__name__}")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise TypeError(f"Dictionary value for key {key!r} must be numeric, not {type(value).__name__}")
            result[key] = result.get(key, 0) + value
    return result
<|return|>

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Define common textual representations of null/None
    NULL_STRINGS = {"none", "null", "nil", "", "n/a", "na"}
    try:
        # Only strings can represent a None value
        if not isinstance(val, str):
            return False
        # Remove leading/trailing whitespace
        stripped = val.strip()
        # Convert to lowercase for case-insensitive comparison
        lowered = stripped.lower()
        return lowered in NULL_STRINGS
    except Exception:
        # In case of unexpected errors, safely return False
        return False<|return|>

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("Expected an argparse.ArgumentParser instance, got %r" % (parser,))
    flags = []
    for action in actions:
        # Only consider actions that have option strings (i.e. optional arguments)
        if hasattr(action, "option_strings"):
            flags.extend(action.option_strings)
    return " ".join(flags)<|return|>

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError("`number` must be an integer")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError("`alphabet` must be a list or tuple of strings")
    if len(alphabet) < 2:
        raise ValueError("Alphabet must contain at least two symbols to represent a base")
    if any(not isinstance(sym, str) or len(sym) == 0 for sym in alphabet):
        raise ValueError("All alphabet entries must be non-empty strings")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("`padding` must be an int or None")
        if padding < 0:
            raise ValueError("`padding` cannot be negative")

    base = len(alphabet)

    # Handle sign
    sign = ""
    n = number
    if n < 0:
        sign = "-"
        n = -n

    # Convert to base
    digits = []
    if n == 0:
        digits.append(alphabet[0])
    else:
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
    digits.reverse()
    digit_str = "".join(digits)

    # Apply padding (if any)
    if padding is not None:
        pad_len = padding - len(digit_str)
        if pad_len > 0:
            digit_str = alphabet[0] * pad_len + digit_str

    return sign + digit_str<|return|>

def replace_dots(value, arg):
    """Replaces all characters '.' in the given string with the specified argument."""
    try:
        if not isinstance(value, str):
            raise TypeError(f"value must be a string, got {type(value).__name__}.")
        if not isinstance(arg, str):
            raise TypeError(f"arg must be a string, got {type(arg).__name__}.")
        return value.replace('.', arg)
    except Exception as exc:
        # Re-raise with contextual information
        raise ValueError(f"Failed to replace dots in '{value}' with '{arg}': {exc}") from exc<|return|>

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class type, got {type(cls).__name__}")
    result = set()
    work = list(cls.__subclasses__())
    while work:
        subclass = work.pop()
        if subclass not in result:
            result.add(subclass)
            work.extend(subclass.__subclasses__())
    return result<|return|>

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Basic validation of alphabet
    if not alphabet:
        raise ValueError("Alphabet must contain at least one symbol.")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet symbols must be unique.")
    if any(not a for a in alphabet):
        raise ValueError("Alphabet cannot contain empty strings.")

    base = len(alphabet)
    if base == 1:
        # Unary: only one digit, numeric value equals the count of that digit
        expected_digit = alphabet[0]
        if not all(ch == expected_digit for ch in string):
            raise ValueError(f"Invalid digits for base-1 system: expected only '{expected_digit}'.")
        return len(string)

    # Map each alphabet symbol to its numeric value
    digit_map = {symbol: idx for idx, symbol in enumerate(alphabet)}

    # Convert string
    value = 0
    for ch in string:
        if ch not in digit_map:
            raise ValueError(f"Character '{ch}' not in alphabet.")
        value = value * base + digit_map[ch]
    return value<|return|>

