def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    if not isinstance(item, dict):
        raise TypeError("Input must be a dictionary")
    converted = {}
    for key, value in item.items():
        if not isinstance(key, str):
            raise TypeError("Dictionary keys must be strings")
        if "*" in key:
            # Escape the key then replace escaped ansterisks with regex wildcards
            pattern = re.escape(key).replace(r"\*", ".*")
        else:
            pattern = key
        converted[pattern] = value
    return converted<|return|>

import shlex
def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if not isinstance(s, str):
        raise TypeError(f"s must be a string, got {type(s).__name__}")

    # Determine POSIX flag based on platform argument
    if platform == 'this':
        # Auto-detect: POSIX for non-Windows, Windows otherwise
        import sys
        posix = not sys.platform.startswith(('win', 'cygwin', 'msys'))
    elif platform == 1:
        posix = True
    elif platform == 0:
        posix = False
    else:
        raise ValueError("platform must be 'this', 1, or 0")

    try:
        return shlex.split(s, posix=posix)
    except ValueError as exc:
        raise RuntimeError(f"Failed to split command line: {exc}") from exc<|return|>

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None

    f = frequency.strip()
    if not f:
        return None

    if f.lower() == 'always':
        return None

    parts = f.split()
    if len(parts) < 2:
        raise ValueError(f'Unable to parse: {frequency}')

    num_str = parts[0]
    unit_str = ' '.join(parts[1:]).lower()

    try:
        num = float(num_str)
    except ValueError:
        raise ValueError(f'Invalid number in frequency: {frequency}')

    # Map unit to timedelta keyword
    if unit_str.startswith('week'):
        # datetime.timedelta accepts weeks as integer only; use days if not integer
        if num.is_integer():
            return datetime.timedelta(weeks=int(num))
        else:
            return datetime.timedelta(days=num * 7)

    if unit_str.startswith('day'):
        return datetime.timedelta(days=num)

    if unit_str.startswith('hour'):
        return datetime.timedelta(hours=num)

    if unit_str.startswith('minute'):
        return datetime.timedelta(minutes=num)

    if unit_str.startswith('second'):
        return datetime.timedelta(seconds=num)

    # These are approximations; not exact in a calendar context
    if unit_str.startswith('month'):
        # average month length in days (30.44)
        return datetime.timedelta(days=num * 30.44)

    if unit_str.startswith('year'):
        # average year length in days (365)
        return datetime.timedelta(days=num * 365)

    raise ValueError(f'Unknown time unit in frequency: {frequency}')<|return|>

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    import socket  # Local import to avoid global dependency

    # Validate input
    if not isinstance(host, str):
        return False
    host_str = host.strip()
    if not host_str:
        return False

    # Quick check for common local identifiers
    low = host_str.lower()
    if low in {"localhost", "127.0.0.1", "::1", "::ffff:127.0.0.1"}:
        return True

    try:
        # Resolve host to all addresses; we don't care about the specific port
        addr_infos = socket.getaddrinfo(host_str, None)
    except socket.gaierror:
        # Unable to resolve hostname
        return False
    except Exception:
        # Catch-all for unexpected errors (e.g., OSError)
        return False

    for family, _, _, _, sockaddr in addr_infos:
        # IPv4
        if family == socket.AF_INET:
            if sockaddr[0] == "127.0.0.1":
                return True
        # IPv6
        if family == socket.AF_INET6:
            addr = sockaddr[0]
            if addr == "::1" or addr == "::":
                return True
            # Handle IPv4-mapped IPv6 for localhost
            if addr == "::ffff:127.0.0.1":
                return True

    # None of the resolved addresses match known localhost forms
    return False<|return|>

def is_gitbash():
    """
    returns True if you run in a Windows gitbash
    :return: True if gitbash
    """
    try:
        # Git Bash sets the MSYSTEM environment variable (e.g., MINGW64, MINGW32, MSYS2) on Windows.
        # If this variable exists, we are most likely running within Git Bash.
        msystem = os.environ.get('MSYSTEM')
        return bool(msystem and msystem.upper().startswith('MINGW'))
    except Exception:
        # If anything goes wrong (e.g., missing os module or access issues), conservatively return False.
        return False<|return|>

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Validate matcher format
    if not isinstance(matcher, (tuple, list)):
        raise TypeError(f"Matcher must be a tuple or list, got {type(matcher).__name__}")
    if len(matcher) == 0:
        raise ValueError("Matcher is empty; expected at least the environment variable name")
    if len(matcher) > 2:
        raise ValueError("Matcher must have 1 or 2 elements: name[, default]")

    name = matcher[0]
    if not isinstance(name, str):
        raise TypeError(f"Environment variable name must be a string, got {type(name).__name__}")

    default_provided = len(matcher) == 2
    default_value = matcher[1] if default_provided else None

    try:
        value = os.environ.get(name)
    except Exception as exc:
        raise RuntimeError(f"Failed to access environment variable '{name}': {exc}") from exc

    if value is not None:
        return value
    if default_provided:
        return default_value

    raise RuntimeError(f"Environment variable '{name}' is not set and no default value provided")<|return|>

def is_ipv4(target):
    """ Test if IPv4 address or not """
    try:
        # ipaddress.ip_address will raise ValueError if the string is not a valid IP
        # and TypeError if target is None or non-string-like.
        ip_obj = ipaddress.ip_address(target)
        return isinstance(ip_obj, ipaddress.IPv4Address)
    except Exception:
        return False<|return|>

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        # Prefer safe_dump if no dumper is provided
        if dumper is None:
            out = yaml.safe_dump(
                obj,
                default_flow_style=False,
                allow_unicode=True,
                explicit_start=False,
                explicit_end=False,
            )
        else:
            out = yaml.dump(
                obj,
                Dumper=dumper,
                default_flow_style=False,
                allow_unicode=True,
                explicit_start=False,
                explicit_end=False,
            )
        # yaml.safe_dump returns a string on py3 and a unicode string on py2.
        # yaml.dump can return bytes on some yaml versions, so normalise to str/unicode.
        if isinstance(out, (bytes, bytearray)):
            return out.decode("utf-8")
        return out
    except Exception as exc:
        raise ValueError(f"Unable to serialise object to yaml string: {exc}") from exc<|return|>

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj`` in case it is a string using UTF-8.
    """
    try:
        if isinstance(obj, str):
            return obj.encode('utf-8')
        else:
