        # If the cache is empty, raise a KeyError as `popitem` normally does.
        if getattr(self, "key_to_val", None) is None or not self.key_to_val:
            raise KeyError("Cache is empty")
        # Use the cached frequency data to identify the LRU of the least frequent bucket.
        freq_to_keys = getattr(self, "freq_to_keys", None)
        key_to_val = self.key_to_val
        key_to_freq = getattr(self, "key_to_freq", None)
        min_freq = getattr(self, "min_freq", None)
        size = getattr(self, "size", None)
        # Fallbacks in case attributes are named differently.
        if freq_to_keys is None:
            freq_to_keys = [k for k, v in self.__dict__.items() if isinstance(v, dict) and k.startswith("freq_")]
            freq_to_keys = freq_to_keys[0] if freq_to_keys else {}
        if min_freq is None:
            # Find the smallest frequency key in the freq_to_keys mapping.
            try:
                min_freq = min(freq_to_keys)
            except Exception:
                min_freq = 0
        try:
            # Pop the oldest key in the bucket of the minimum frequency.
            key, _ = freq_to_keys[min_freq].popitem(last=False)
            val = key_to_val.pop(key)
            if key_to_freq is not None:
                key_to_freq.pop(key, None)
            if size is not None:
                self.size = size - 1
        except Exception as e:
            raise KeyError(f"Failed to pop item: {e}") from e
        # Clean up if the bucket is now empty.
        if freq_to_keys and not freq_to_keys[min_freq]:
            del freq_to_keys[min_freq]
            # Update the next minimum frequency if any items remain.
            if getattr(self, "size", 0) > 0:
                try:
                    self.min_freq = min(freq_to_keys)
                except Exception:
                    self.min_freq = 0
            else:
                self.min_freq = 0
