    """Remove and return the `(key, value)` pair least recently used."""
    # LRU caches typically keep an ordered mapping (e.g., OrderedDict).
    # Try to use the OrderedDict popitem(last=False) method, falling back
    # for plain dicts when order by recency is not guaranteed.
    try:
        # OrderedDict or a similar type
        return self._data.popitem(last=False)
    except (AttributeError, TypeError):
        # If popitem doesn't accept the `last` kwarg, use explicit logic.
        # Ensure the cache is not empty.
        if not hasattr(self, "_data") or not self._data:
            raise KeyError("popitem(): dictionary is empty")
        # Get the first (least recently used) item.
        key, value = next(iter(self._data.items()))
        del self._data[key]
        return key, value
