                # Fall back to generic popitem which pops arbitrary pair (defaults to LRU in CPython 3.7+)
                return mapping.popitem()
            except KeyError:
                # Re‑raise with a clearer message.
                raise KeyError("popitem(): dictionary is empty") from None
