    """Remove and return a random `(key, value)` pair."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    try:
        import random
    except Exception:
        # Fallback if random cannot be imported (unlikely in standard Python)
        keys = list(self.keys())
        if not keys:
            raise KeyError("popitem(): dictionary is empty")
        key = keys[0]
    else:
        key = random.choice(list(self.keys()))
    value = self.pop(key)
    return key, value<|return|>

