def default_tzinfo(dt, tzinfo):
    """
    Sets the ``tzinfo`` parameter on naive datetimes only.

    :param dt: :py:class:`datetime.datetime` instance to adjust.
    :param tzinfo: :py:class:`datetime.tzinfo` subclass instance to
                   assign to ``dt`` if it is naive.
    :return: A new :py:class:`datetime.datetime` that is aware.
    :raises TypeError: If ``dt`` is not a datetime instance or
                       ``tzinfo`` is not a tzinfo instance.
    """
    # Validate dt
    if not hasattr(dt, "__class__") or not hasattr(dt, "tzinfo") or not hasattr(dt.tzinfo, "__class__"):
        raise TypeError("dt must be a datetime.datetime instance")
    # Validate tzinfo
    try:
        # A tzinfo instance must have utcoffset method
        if tzinfo is None or not hasattr(tzinfo, "utcoffset"):
            raise TypeError
    except Exception:
        raise TypeError("tzinfo must be an instance of datetime.tzinfo")
    # If datetime is naive, set the tzinfo
    if dt.tzinfo is None:
        try:
            return dt.replace(tzinfo=tzinfo)
        except Exception as exc:
            raise TypeError(f"Failed to replace tzinfo: {exc}") from exc
    # If already aware, return as-is
    return dt
