def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        # Extract payload dict from request
        payload = None
        # Common HTTP frameworks expose a `.json()` method
        if hasattr(request, "json") and callable(request.json):
            payload = request.json()
        # Some frameworks expose a `.body` attribute
        elif hasattr(request, "body"):
            body = request.body
            if isinstance(body, dict):
                payload = body
            # If body is a str, we cannot parse it without json, so skip
        # Accept plain dicts
        elif isinstance(request, dict):
            payload = request

        if not isinstance(payload, dict):
            return False

        # Check for public message structure
        if "public" in payload and isinstance(payload["public"], dict):
            return True

        # Check for private message structure
        if "private" in payload and isinstance(payload["private"], dict):
            return True

        # Legacy payload may use various markers
        legacy_markers = {"diaspora", "legacy", "message"}
        if any(key in payload for key in legacy_markers):
            return True

        # Additional legacy checks based on typical content keys
        msg = payload.get("message")
        if isinstance(msg, dict):
            if any(k in msg for k in ("content", "type", "thread")):
                return True

        return False
    except Exception:
        return False<|return|>

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        if request is None:
            return False

        # Get the request path if available
        path = None
        if hasattr(request, "path"):
            path = getattr(request, "path", None)
        elif hasattr(request, "url"):
            url = getattr(request, "url", None)
            if isinstance(url, str):
                # Strip query parameters
                url = url.split("?", 1)[0]
                # Remove protocol and host if present
                if "://" in url:
                    url = url.split("://", 1)[1]
                # Extract the path component
                parts = url.split("/", 1)
                if len(parts) == 2:
                    path = "/" + parts[1]
                else:
                    path = "/"

        if isinstance(path, str) and path.lower().startswith("/_matrix"):
            return True

        # Check headers for Matrix specific content type
        hdrs = getattr(request, "headers", None)
        if hdrs is not None:
            if isinstance(hdrs, dict):
                ct = hdrs.get("content-type", "")
            else:
                # Try to call a get method if available
                get_method = getattr(hdrs, "get", None)
                ct = get_method("content-type", "") if callable(get_method) else ""
            if isinstance(ct, str) and "application/json" in ct.lower():
                return True

        return False
    except Exception:
        # Any unexpected error results in a conservative FALSE
        return False<|return|>

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    # Handle None or invalid node input.
    if node is None:
        return {}

    try:
        # Try to iterate children; works with ElementTree and lxml elements.
        children = list(node)
    except Exception:
        # If node is not iterable or not an element, return empty dict.
        return {}

    result = {}
    for child in children:
        try:
            tag = child.tag
        except Exception:
            # If child has no tag, skip it.
            continue

        # Store the child; if the tag appears multiple times, collect them in a list.
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child

    return result<|return|>

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # pylint: disable=missing-docstring
    from urllib.parse import urlparse

    # Basic validation of the supplied URL
    try:
        parsed = urlparse(url)
    except Exception as exc:
        raise ValueError(f"Invalid URL '{url}': {exc}") from exc

    if parsed.scheme not in ("http", "https"):
        raise ValueError(f"URL must start with http:// or https://, got: '{url}'")
    if not parsed.netloc:
        raise ValueError(f"URL must contain a valid hostname, got: '{url}'")

    # Determine the document path
    if document_path is None:
        # Default path used by the NodeInfo spec (version 2.0)
        document_path = "/.well-known/nodeinfo/2.0"
    else:
        # Normalise supplied path: ensure it starts with a slash
        document_path = document_path if document_path.startswith("/") else f"/{document_path}"

    # Build the href, avoiding double slashes when joining
    base = f"{parsed.scheme}://{parsed.netloc}"
    href = base.rstrip("/") + document_path

    # Construct the well‑known document as a dictionary
    well_known_doc = {
        "@context": "https://www.w3.org/ns/nodeinfo",
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/core/2.0",
                "href": href,
            }
        ],
    }

    return well_known_doc<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which can be in either the new JSON format or the older XRD XML format.

    :param document: The raw webfinger document as a string.
    :return: A dictionary containing at least the keys 'subject', 'aliases', 'links', and optionally 'properties'.
    """
    import json
    import xml.etree.ElementTree as ET

    def _extract_from_json(obj: Dict) -> Dict:
        """Extract fields from a JSON webfinger object."""
        subject = obj.get("subject")
        aliases = obj.get("aliases", [])
        properties = obj.get("properties", {})
        links_list = obj.get("links", [])
        links = {}
        for link in links_list:
            if not isinstance(link, dict):
                continue
            rel = link.get("rel")
            href = link.get("href") or link.get("template")
            if rel and href:
                links.setdefault(rel, []).append(href)
        result = {"subject": subject, "aliases": aliases, "links": links}
        if properties:
            result["properties"] = properties
        return result

    def _extract_from_xrd(xml_str: str) -> Dict:
        """Parse XRD (XML) webfinger and extract relevant fields."""
        ns = {"xri": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        try:
            root = ET.fromstring(xml_str)
        except ET.ParseError:
            return {}
        # subject
        subject_elem = root.find("xri:Subject", ns)
        subject = subject_elem.text if subject_elem is not None else None
        # aliases
        aliases = [e.text for e in root.findall("xri:Alias", ns) if e.text]
        # links
        links = {}
        for link in root.findall("xri:Link", ns):
            rel = link.get("rel")
            href = link.get("href") or link.get("template")
            if rel and href:
                links.setdefault(rel, []).append(href)
        result = {"subject": subject, "aliases": aliases, "links": links}
        return result

    # If the document is empty or whitespace, return an empty dict
    if not document or not document.strip():
        return {}

    # Attempt JSON parsing first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            return _extract_from_json(data)
    except json.JSONDecodeError:
        pass

    # Fallback to XRD parsing
    return _extract_from_xrd(document) if isinstance(document, str) else {}
<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.

    Parameters
    ----------
    handle : str
        The account handle in the form 'user@example.com'.

    Returns
    -------
    Optional[str]
        The JSON content of the webfinger document as a string if successfully retrieved,
        otherwise None.
    """
    if not handle or not isinstance(handle, str):
        return None

    # Validate the handle format (must contain '@')
    try:
        local_part, domain = handle.rsplit("@", 1)
    except ValueError:
        return None

    # Encode each component for use in the URL
    from urllib.parse import quote
    resource_query = f"resource=acct:{quote(handle)}"

    # Construct URLs with HTTPS first, then fallback to HTTP if HTTPS fails
    base_url_https = f"https://{domain}/.well-known/webfinger"
    base_url_http = f"http://{domain}/.well-known/webfinger"

    # Helper function to perform the request
    def _fetch(url: str) -> Optional[str]:
        from urllib.request import Request, urlopen
        from urllib.error import URLError, HTTPError

        try:
            req = Request(f"{url}?{resource_query}", headers={"Accept": "application/json"})
            with urlopen(req, timeout=5) as response:
                # Only consider 2xx responses as success
                if 200 <= response.getcode() < 300:
                    try:
                        return response.read().decode("utf-8")
                    except Exception:
                        # Possibly non-UTF-8 content; try latin-1 fallback
                        try:
                            return response.read().decode("latin-1")
                        except Exception:
                            return None
                else:
                    return None
        except (HTTPError, URLError, ValueError):
            return None

    # Try HTTPS first
    content = _fetch(base_url_https)
    if content is not None:
        return content

    # Fallback to HTTP
    return _fetch(base_url_http)<|return|>

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import urllib.request
    import urllib.error

    # Ensure the host URL is well-formed
    if not host.startswith(("http://", "https://")):
        host = "https://" + host

    host_meta_url = host.rstrip("/") + "/.well-known/host-meta"

    try:
        with urllib.request.urlopen(host_meta_url, timeout=5) as response:
            if response.status != 200:
                raise ValueError(
                    f"Failed to retrieve host-meta: HTTP status {response.status}"
                )
            xml_data = response.read().decode("utf-8")
    except urllib.error.URLError as exc:
        raise ValueError(f"Unable to retrieve host-meta from {host}: {exc}") from exc
    except Exception as exc:
        raise ValueError(f"Error retrieving host-meta from {host}: {exc}") from exc

    try:
        from diaspora_lib import XRD
    except ImportError as exc:
        raise ImportError("The 'diaspora_lib' package is required to parse host-meta") from exc

    try:
        xrd_instance = XRD.load(xml_data)
    except Exception as exc:
        raise ValueError(f"Error parsing host-meta XML: {exc}") from exc

    return xrd_instance<|return|>

