            raise IRValidatorException(f"Error parsing YAML file: {yaml_file}") from e
        except Exception as e:
            raise IRValidatorException(f"Unexpected error reading YAML file: {yaml_file}") from e

        if data is None:
            data = {}
        if not isinstance(data, dict):
            raise IRValidatorException(f"YAML file {yaml_file} does not contain a mapping at top level")

        required = getattr(cls, 'required_fields', None)
        if required is None:
            raise IRValidatorException("No required_fields attribute defined on class")
        if not isinstance(required, (set, list, tuple)):
            raise IRValidatorException("required_fields must be an iterable of field names")

        missing = [key for key in required if key not in data]
        if missing:
            raise IRValidatorException(f"Missing required fields in {yaml_file}: {', '.join(missing)}")

        return data<|return|>

def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        # Basic input validation
        if not isinstance(cli_args, dict):
            raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
        if not isinstance(answer_file_args, dict):
            raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

        # Retrieve a set of deprecated argument names.  Try a few common attribute names
        deprecated = getattr(self, "deprecated_args", None)
        if deprecated is None:
            deprecated = getattr(self, "deprecated_params", None)
        if deprecated is None:
            deprecated = getattr(self, "deprecated", None)
        if not isinstance(deprecated, (set, list, tuple)):
            deprecated = set()
        else:
            deprecated = set(deprecated)

        # Helper to warn
        def _warn(arg_name):
            try:
                # Use the object's logger if available
                logger = getattr(self, "logger", None)
                if logger and hasattr(logger, "warning"):
                    logger.warning(f"Argument '{arg_name}' is deprecated and may be removed in future releases.")
                else:
                    print(f"WARNING: Argument '{arg_name}' is deprecated and may be removed in future releases.")
            except Exception:
                # Fallback: just print
                print(f"WARNING: Argument '{arg_name}' is deprecated and may be removed in future releases.")

        # Check CLI arguments
        for key in cli_args:
            if key in deprecated:
                _warn(key)

        # Check answer file arguments
        for key in answer_file_args:
            if key in deprecated:
                _warn(key)

        return None<|return|>

def get_option_spec(self, command_name, argument_name):
        """Gets the specification for the specified option name. """
        # Validate inputs
        if not isinstance(command_name, str) or not command_name:
            raise ValueError("command_name must be a non-empty string")
        if not isinstance(argument_name, str) or not argument_name:
            raise ValueError("argument_name must be a non-empty string")

        try:
            # Retrieve the command holder (could be dict or object)
            command = getattr(self, "commands", {}).get(command_name)
            if command is None:
                raise KeyError(f"Command '{command_name}' not found.")

            # Determine where options are stored
            options = None
            if isinstance(command, dict):
                options = command
            else:
                options = getattr(command, "options", None)

            if options is None or not isinstance(options, dict):
                raise AttributeError(f"Unable to find options for command '{command_name}'")

            # Retrieve the specific option spec
            spec = options.get(argument_name)
            if spec is None:
                raise KeyError(f"Option '{argument_name}' not found for command '{command_name}'")

            return spec

        except Exception as exc:
            # Wrap all unexpected errors in a RuntimeError with context
            raise RuntimeError(
                f"Failed to get option spec for command '{command_name}', "
                f"option '{argument_name}': {exc}"
            ) from exc
