def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec: the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    # Validate inputs
    if not isinstance(options_spec, (list, tuple)):
        raise TypeError("options_spec must be a list or tuple of option specs")
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of provided arguments")

    required_names = []

    # Helper to determine if condition matches
    def _condition_matches(condition):
        """
        Check if a given condition evaluates to True for the current context.
        Supports callables, dicts, lists/tuples, strings, and booleans.
        """
        try:
            if callable(condition):
                # Try passing command_name and args; fall back to args only
                try:
                    result = condition(command_name, args)
                except TypeError:
                    result = condition(args)
                return bool(result)

            if isinstance(condition, dict):
                # Each key/value pair must match the corresponding arg value
                for key, expected in condition.items():
                    val = args.get(key)
                    if isinstance(expected, (list, tuple, set)):
                        if val not in expected:
                            return False
                    else:
                        if val != expected:
                            return False
                return True

            if isinstance(condition, (list, tuple)):
                # Treat each element as a pair or a single key
                for item in condition:
                    if isinstance(item, (list, tuple)) and len(item) == 2:
                        key, expected = item
                        val = args.get(key)
                        if isinstance(expected, (list, tuple, set)):
                            if val not in expected:
                                return False
                        else:
                            if val != expected:
                                return False
                    else:
                        # Single key that must evaluate truthily
                        key = item
                        if not args.get(key):
                            return False
                return True

            if isinstance(condition, str):
                # A single key that must evaluate truthily
                return bool(args.get(condition))

            if isinstance(condition, bool):
                return condition

            # Unsupported condition type, treat as not matched
            return False

        except Exception:
            # Any error during condition evaluation treats it as not matched
            return False

    for spec in options_spec:
        # Ensure it's a dict-like spec
        if not isinstance(spec, dict):
            continue
        option_name = spec.get("name")
        if not option_name:
            continue

        cond = spec.get("required_when")
        if cond is None:
            continue

        if _condition_matches(cond):
            required_names.append(option_name)

    return required_names<|return|>

def validate_length_args(self, args):
        """
        Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        """
        # Ensure args is a dictionary-like or iterable of (name, value) pairs.
        if args is None:
            return

        # Helper to obtain length if possible
        def get_length(val):
            try:
                return len(val)
            except Exception:
                return None

        # Determine if args is a mapping or a sequence of values
        if isinstance(args, dict):
            items = args.items()
        else:
            # For non-dict iterables, try to treat each element as a value or (name, value) tuple
            try:
                items = ((idx, val) for idx, val in enumerate(args))
            except Exception:
                # Arg cannot be iterated; nothing to validate
                return

        # Iterate through each argument and validate its length
        for name, value in items:
            # Skip null values
            if value is None:
                continue

            # Retrieve the maximum allowed length for this argument, if configured
            # Attempt to get it from a class attribute 'max_lengths' mapping names to limits
            max_len = getattr(self, "max_lengths", {}).get(name)

            # If no max length specified, skip validation for this argument
            if max_len is None:
                continue

            # Determine the actual length of the argument
            actual_len = get_length(value)

            # If actual length cannot be determined, skip
            if actual_len is None:
                continue

            # Compare against the specified maximum
            if actual_len > max_len:
                raise ValueError(
                    f"Argument '{name}' length {actual_len} exceeds maximum allowed {max_len}."
                )<|return|>

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments (a mapping of argument names to values).
    """
    # If self doesn't expose a choices mapping, nothing to validate.
    if not hasattr(self, "_choices"):
        return

    choices_map = getattr(self, "_choices")
    if not isinstance(choices_map, dict):
        return

    for arg_name, arg_value in args.items():
        # Skip if this argument has no defined choices.
        if arg_name not in choices_map:
            continue
        allowed = choices_map[arg_name]
        if allowed is None:
            continue
        # Determine if the argument accepts multiple values (e.g., multi-select).
        if isinstance(arg_value, (list, tuple, set)):
            # Find any values that are not in the allowed set.
            invalid = [v for v in arg_value if v not in allowed]
            if invalid:
                raise ValueError(
                    f"Invalid choice(s) {invalid!r} for option '{arg_name}'. "
                    f"Allowed: {list(allowed)}"
                )
        else:
            if arg_value not in allowed:
                raise ValueError(
                    f"Invalid choice {arg_value!r} for option '{arg_name}'. "
                    f"Allowed: {list(allowed)}"
                )
    # If no exception was raised, all choice arguments are valid.<|return|>

