def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    """
    Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation
    if not isinstance(subcommand, str):
        raise TypeError(f"subcommand must be a string, got {type(subcommand).__name__}")
    if not isinstance(type_name, str):
        raise TypeError(f"type_name must be a string, got {type(type_name).__name__}")
    if not isinstance(option_name, str):
        raise TypeError(f"option_name must be a string, got {type(option_name).__name__}")
    if spec_option is None or not isinstance(spec_option, dict):
        raise TypeError(f"spec_option must be a dict, got {type(spec_option).__name__}")

    # Extract optional field definitions
    fields = spec_option.get("fields")
    if fields is not None and not isinstance(fields, dict):
        raise TypeError("spec_option['fields'] must be a dict if provided")

    # Define the __init__ method for the dynamic class
    def __init__(self_, *args, **kwargs):
        if fields:
            # Expect either a single positional tuple for all fields
            if len(args) == 1 and isinstance(args[0], (tuple, list)):
                values = args[0]
                if len(values) != len(fields):
                    raise ValueError(f"Expected {len(fields)} values for fields, got {len(values)}")
                for name, value in zip(fields.keys(), values):
                    setattr(self_, name, value)
            else:
                # Keyword arguments
                for name in fields:
                    if name not in kwargs:
                        raise TypeError(f"Missing required field '{name}' for complex type '{type_name}'")
                    setattr(self_, name, kwargs.pop(name))
                if kwargs:
                    raise TypeError(f"Unexpected keyword arguments: {', '.join(kwargs.keys())}")
            # Store any extra attributes
            if args and not fields:
                if len(args) > 1:
                    raise TypeError(f"Expected at most one positional argument for complex type '{type_name}'")
                setattr(self_, "value", args[0])
        else:
            # Simple wrapper around a single value
            if len(args) != 1:
                raise TypeError(f"Complex type '{type_name}' expects exactly one positional argument")
            setattr(self_, "value", args[0])

        # Attach meta information
        self_.subcommand = subcommand
        self_.option_name = option_name

    # Define a simple __repr__ for debugging
    def __repr__(self_):
        if fields:
            field_strings = [f"{k}={getattr(self_, k)!r}" for k in fields]
            return f"<{type_name} {' '.join(field_strings)}> (subcommand={self_.subcommand!r}, option={self_.option_name!r})"
        else:
            return f"<{type_name} value={getattr(self_, 'value', None)!r}> (subcommand={self_.subcommand!r}, option={self_.option_name!r})"

    # Construct the dynamic class dictionary
    class_dict = {"__init__": __init__,
                  "__repr__": __repr__}
    # Include the fields as class attributes with default None for type introspection
    if fields:
        for field_name in fields:
            class_dict[field_name] = None

    # Create the dynamic class
    ComplexType = type(type_name, (object,), class_dict)

    return ComplexType
<|return|>

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        control_args = {}
        nested_args = {}

        # Handle None input gracefully
        if args is None:
            return control_args, nested_args

        # Normalize args to an iterable of key/value pairs
        try:
            if isinstance(args, dict):
                items = args.items()
            else:
                # Support list/tuple of tuples or strings like "key=value"
                items = []
                for item in args:
                    if isinstance(item, tuple) and len(item) == 2:
                        items.append(item)
                    elif isinstance(item, str):
                        if '=' in item:
                            key, val = item.split('=', 1)
                            items.append((key, val))
                        else:
                            items.append((item, None))
                    else:
                        # Skip unrecognized item types
                        continue
        except Exception:
            # If items cannot be represented as key/value pairs, return empty dicts
            return control_args, nested_args

        for key, value in items:
            if key is None:
                continue

            try:
                # Normalize key for prefix checks
                key_str = str(key)
                key_lower = key_str.lower()
            except Exception:
                continue

            # Identify control arguments by prefix
            if key_lower.startswith(('control_', 'ctrl_')):
                control_args[key_str] = value
            else:
                # Custom arguments override nested by stripping "custom_"
                if key_lower.startswith('custom_'):
                    custom_key = key_str[len('custom_'):]
                    nested_args[custom_key] = value
                else:
                    nested_args[key_str] = value

        return control_args, nested_args<|return|>

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    # Basic validation of inputs
    if not isinstance(cli_args, list):
        raise TypeError("cli_args must be a list of arguments")
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if ir_workspace is None:
        raise ValueError("ir_workspace cannot be None")
    if ir_plugin is None:
        raise ValueError("ir_plugin cannot be None")

    # Build the extra-vars string from the dictionary
    # Use simple string formatting; this supports only basic types
    if vars_dict:
        try:
            extra_vars_parts = []
            for key, value in vars_dict.items():
                if isinstance(value, (dict, list)):
                    # Convert complex structures to string representation
                    value_str = str(value)
                else:
                    value_str = str(value)
                extra_vars_parts.append(f"{key}={value_str}")
            extra_vars_string = " ".join(extra_vars_parts)
        except Exception as gen_exc:
            raise RuntimeError(f"Failed to build extra-vars string: {gen_exc}") from gen_exc
    else:
        extra_vars_string = None

    # Assemble final command arguments
    command_args = list(cli_args)  # copy to avoid modifying caller list
    if extra_vars_string is not None:
        command_args.extend(["--extra-vars", extra_vars_string])

    # Execute the command via the Infrared plugin
    try:
        # Infrared plugins typically expose a method `_run_cli` that returns
        # a dictionary containing at least 'exit_code', 'stdout', and 'stderr'.
        # If the method differs, the calling code is expected to adapt this
        # function accordingly.
        result = ir_plugin._run_cli(command_args, capture_output=True)
        return result
    except Exception as run_exc:
        raise RuntimeError(f"Ansible playbook execution failed: {run_exc}") from run_exc<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict in place.

    By default all the values are strings.  This function attempts to infer the
    intended Python type for each argument value using either an explicit type
    mapping (if present) or heuristics.  Conversion errors are ignored so that
    the parsing continues with the original string value.

    Parameters
    ----------
    parser_name : str
        The command name, e.g. "main", "virsh", "ospd", etc.
    values_dict : dict
        The dictionary of arguments (string keys, string values).

    Returns
    -------
    dict
        The same dictionary, with values possibly converted to int, float,
        bool, None, lists or kept as strings.
    """
    # Helper to convert common string representations to boolean.
    def _str_to_bool(v):
        true_set = {"true", "yes", "1"}
        false_set = {"false", "no", "0"}
        try:
            if isinstance(v, str):
                low = v.lower().strip()
                if low in true_set:
                    return True
                if low in false_set:
                    return False
            # Fallback: truthiness of the string
            return bool(v)
        except Exception:
            return v

    # If the class stores per-parser type mappings, use them; otherwise
    # rely purely on heuristics.
    type_map = getattr(self, "_parser_arg_types", {}).get(parser_name, {})

    for key, raw_value in values_dict.items():
        # Preserve non-string values untouched.
        if not isinstance(raw_value, str):
            continue

        value = raw_value.strip()

        # ----- Explicit mapping based conversion -----
        if key in type_map:
            target_type = type_map[key]
            try:
                if target_type is bool:
                    values_dict[key] = _str_to_bool(value)
                else:
                    values_dict[key] = target_type(value)
                continue
            except Exception:
                # If conversion fails, fall through to heuristics.
                pass

        # ----- Heuristic based conversion -----
        # None
        if value.lower() == "none":
            values_dict[key] = None
            continue

        # Boolean
        if value.lower() in ("true", "false", "yes", "no", "1", "0"):
            values_dict[key] = _str_to_bool(value)
            continue

        # Integer
        if value.isdigit() or (value.startswith("-") and value[1:].isdigit()):
            try:
                values_dict[key] = int(value)
                continue
            except ValueError:
                pass

        # Float
        try:
            fvalue = float(value)
            if "." in value or "e" in value.lower():
                values_dict[key] = fvalue
                continue
        except ValueError:
            pass

        # Comma‑separated list
        if "," in value:
            try:
                list_vals = [x.strip() for x in value.split(",")]
                values_dict[key] = list_vals
                continue
            except Exception:
                pass

        # Fallback: keep original string
        values_dict[key] = raw_value

    return values_dict
<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:  # pragma: no cover
        yaml = None

    if not os.path.isdir(plugin_dir):
        raise ValueError(f"plugin_dir must be an existing directory: {plugin_dir}")

    # Look for common spec file names
    spec_filenames = ("plugin.json", "plugin.yaml", "plugin.yml")
    spec_path = None
    for name in spec_filenames:
        potential = os.path.join(plugin_dir, name)
        if os.path.isfile(potential):
            spec_path = potential
            break

    if spec_path is None:
        raise FileNotFoundError(
            f"No plugin spec file ({', '.join(spec_filenames)}) found in {plugin_dir}"
        )

    # Load the spec
    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            content = f.read()
    except Exception as exc:  # pragma: no cover
        raise RuntimeError(f"Failed to read spec file: {exc}") from exc

    try:
        if spec_path.endswith(".json"):
            data = json.loads(content)
        else:
            if yaml is not None:
                data = yaml.safe_load(content)
            else:
                # Fallback to JSON for YAML files if PyYAML isn't available
                data = json.loads(content)
    except Exception as exc:  # pragma: no cover
        raise RuntimeError(f"Failed to parse plugin spec: {exc}") from exc

    # Flatten nested structures
    flat = {}

    def _flatten(obj, prefix=""):
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_prefix = f"{prefix}.{k}" if prefix else k
                _flatten(v, new_prefix)
        elif isinstance(obj, list):
            for idx, item in enumerate(obj):
                new_prefix = f"{prefix}.{idx}" if prefix else str(idx)
                _flatten(item, new_prefix)
        else:
            flat[prefix] = obj

    _flatten(data)
    return flat<|return|>

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        env_var = "CONFIG_PATH"
        # If the variable already exists and is non-empty, do nothing
        if os.environ.get(env_var):
            return
        # Determine a sensible default path (e.g., config.yaml in the current working directory)
        default_path = os.path.join(os.getcwd(), "config.yaml")
        os.environ[env_var] = default_path
    except Exception as exc:
        raise RuntimeError(f"Could not inject config path: {exc}") from exc<|return|>
